'use strict';

(function(){
  const ix4=['iX4-200 Pro','iX4-240 Pro','iX4-250 Pro','iX4-350 Pro'];
  addRepairKB({id:'argox-ix4pro-cutter-install-service',brand:'Argox',models:ix4,title:'iX4 Pro｜Cutter 安裝／更換後不動、卡刀、切位驗證',category:'原廠配件／Cutter',severity:'A｜原廠指南',summary:'Argox 官方提供 iX4 Pro / DX4 Pro Cutter Quick Installation Guide。遇到新裝 Cutter 不動或更換後卡刀時，先確認模組版本、安裝與接線，再進 Print Mode、Home/動作與切位驗證，不直接判主板。',keyFacts:['官方下載中心列有 iX4 Pro / DX4 Pro Series Cutter Quick Installation Guide V1.0。','新裝後完全不動先分安裝/接線/設定，再分 Cutter 機構或驅動。','更換 Cutter 後需要用實際紙材確認切位與連續切紙，不只看單次動作。'],engineering:['拆裝前斷電，先拍原模組、接頭與走線。','模組安裝完成後先手動確認紙路無異物與機構未卡死，再上電。','若 Cutter 有動但位置錯，先確認 Label Length/Calibration，再調 Cut Offset；不要先改多個參數。'],verify:['開機無 Cutter 錯誤','連續切 50 次無卡刀','切位一致','斷電重開後仍正常'],flow:[['核對模組/指南','確認 iX4 Pro 適用 Cutter 與官方安裝指南。',['已確認','不確定'],'版本不確定先不要上電。'],['斷電檢查安裝/接線','看固定、接頭、線束、刀區與紙路。',['正常','發現裝配異常'],'裝配異常先修。'],['上電確認 Cutter 模式','確認 Driver/Printer 設定真的使用 Cutter。',['設定正確','設定錯誤'],'設定錯先修。'],['觀察動作','完全不動、動一下卡住、可切但位置錯。',['完全不動','卡住','切位錯','正常'],'依結果分流。'],['連續切/冷啟驗證','用客戶紙連續切並重開機再測。',['通過','失敗'],'失敗回接線/機構/設定。']],sources:['argox_ix4_accessories','argox_ix4pro'],evidence:'source-backed'});

  addRepairKB({id:'argox-ix4pro-peeler-install-service',brand:'Argox',models:ix4,title:'iX4 Pro｜Peeler 安裝後不剝紙／Take Label 不回復',category:'原廠配件／Peeler',severity:'A｜原廠指南',summary:'Argox 官方下載中心列有 iX4 Pro / iX6 Pro Peeler Quick Installation Guide。安裝後不剝紙或停在 Take Label 類狀態時，先確認底紙路徑、Peeler 模組與感應器/接線，再確認列印模式。',keyFacts:['Peeler 是選配，設定為 Peel 模式但實機模組/感應器未正確安裝會造成流程異常。','底紙穿法、剝離位置與 Label Taken/Peel sensing 要一起確認。','更換或重裝後要用實際標籤測剝離，不只空跑 FEED。'],engineering:['斷電拆裝並拍底紙路徑。','先確認標籤可正常剝離，不要用過硬/特殊底紙直接判模組壞。','若感應器遮擋前後讀值不變，再進 Sensor/線束交叉。'],verify:['Peel 模式一張一停','取標後可繼續','底紙回收/路徑正常','連續 30~50 張無卡紙'],flow:[['確認有安裝 Peeler','核對模組與官方指南。',['有','沒有/不確定'],'沒有模組不要開 Peel。'],['檢查底紙路徑','依模組路徑重穿底紙與標籤。',['正確','已修正'],'先排穿法。'],['確認模式/感應器','Peel 模式與 Take Label/Peel sensing。',['正常','設定異常','Sensor 無反應'],'Sensor 無反應進硬體。'],['實際剝離測試','用客戶標籤測取標與下一張動作。',['正常','不剝/不停','卡紙'],'依結果收斂。'],['長測','連續取標並重開機再驗證。',['通過','失敗'],'失敗保留條件。']],sources:['argox_ix4_accessories','argox_ix4pro'],evidence:'source-backed'});

  addRepairKB({id:'argox-ix4pro-internal-rewinder-install',brand:'Argox',models:ix4,title:'iX4 Pro｜Internal Rewinder 安裝後不回捲／張力異常',category:'原廠配件／Rewinder',severity:'A｜原廠指南',summary:'Argox 官方提供 iX4 Pro Series Internal Rewinder Quick Installation Guide。回捲器新裝後不轉、太鬆或拉紙時，先分安裝/路徑、Rewind 設定、Clutch/傳動與驅動，不直接把回捲問題判成 Mainboard。',keyFacts:['官方下載中心列有 iX4 Pro Series Internal Rewinder Quick Installation Guide V1.0。','回捲器不轉要先確認機器是否真的在 Rewind 使用模式與紙路是否符合。','張力過高也會造成走紙/定位問題，因此「會轉」不代表正常。'],engineering:['斷電確認 Rewinder 模組固定與線束。','空載與實際底紙/標籤負載分開測，觀察是否只有負載下打滑。','有馬達/傳動聲但軸不帶動，優先看 Gear/Clutch/軸，不先換板。'],verify:['回捲方向正確','張力不拉偏紙','連印 50~100 張定位正常','停機/重開後功能正常'],flow:[['核對安裝與紙路','依官方 Internal Rewinder 指南確認。',['正確','已修正'],'先排裝配。'],['確認 Rewind 模式','機器/Driver 設定與實際應用一致。',['正確','設定錯'],'設定錯先修。'],['觀察空載/負載','軸完全不轉、空載轉負載打滑、張力過大。',['不轉','打滑','過緊','正常'],'分流傳動/Clutch/設定。'],['查線束/傳動','斷電檢查接頭、Gear/Clutch/軸。',['找到異常','正常'],'正常才往驅動。'],['長測定位','連印並觀察紙路與回捲張力。',['通過','失敗'],'失敗回走紙/張力。']],sources:['argox_ix4_accessories','argox_ix4pro'],evidence:'source-backed'});

  addRepairKB({id:'argox-p4pro-cutter-peeler-install',brand:'Argox',models:['P4-250 Pro','P4-350 Pro','P4-650 Pro'],title:'P4 Pro｜Guillotine / Rotary Cutter、Peeler 安裝後功能異常',category:'原廠配件／Cutter／Peeler',severity:'A｜原廠指南',summary:'Argox 官方下載中心列有 P4 Pro Guillotine Cutter、Rotary Cutter 與 Peeler Quick Installation Guide。新裝或更換選配後異常時，先核對選配類型與安裝，再進設定、Sensor、切位/剝離測試。',keyFacts:['P4 Pro 的 Guillotine Cutter 與 Rotary Cutter 是不同選配，排查時要先確認實機類型。','Peeler 與 Cutter 的紙路/模式不同，不能只靠 Driver 名稱判斷。','安裝後要重新用實際標籤測 Cut/Peel position。'],engineering:['拆裝前斷電，記錄選配模組與接頭。','不要把 Guillotine 與 Rotary 的機構行為互套。','更換選配後固定偏移先確認 Calibration/Label Length，再調 Offset。'],verify:['選配被正確使用','Cut/Peel position 正常','連續動作無卡滯','斷電重開後設定保存'],flow:[['辨識選配','Guillotine / Rotary Cutter / Peeler。',['已辨識','不確定'],'不確定先查模組/指南。'],['核對安裝','依官方 Quick Installation Guide 查固定、紙路、接線。',['正確','已修正'],'先修裝配。'],['確認模式','Driver/Printer 的 Cut/Peel 模式。',['正確','錯誤'],'錯誤先修。'],['實際功能測試','觀察不動、卡住、位置錯、剝離異常。',['不動','卡滯','位置錯','正常'],'依結果分流。'],['長測','客戶實際耗材連續測試。',['通過','失敗'],'失敗保留條件再查。']],sources:['argox_p4_accessories','argox_p4pro'],evidence:'source-backed'});

  addRepairKB({id:'honeywell-pm45-interface-accessory-guide',brand:'Honeywell (Datamax/Intermec)',models:['PM45'],title:'PM45｜Interface Board／Accessory 更換或加裝後不辨識',category:'原廠配件／Interface Board',severity:'A｜原廠指南',summary:'Honeywell 2026 官方資源列有 PM45/PM45c/PM65 Interface Boards And Accessories User Guide。加裝或更換介面板/配件後異常時，應依該指南核對相容性、安裝與設定，再做通訊/選配驗證。',keyFacts:['Honeywell 官方 PM45 產品資源提供 Interface Boards And Accessories User Guide Rev C（2026）。','介面/配件更換後不應只看是否能開機；要驗證該介面、設定與實際工作負載。','不同板件/配件的接頭與安裝步驟應依官方 accessory guide，不自行沿用其他 Honeywell 機型。'],engineering:['換前保存 Network/Interface 設定與板件照片。','ESD、斷電後再拆裝板件。','新板不辨識時先查安裝/相容性/設定，再查主板。'],verify:['開機穩定','介面可被辨識','實際 USB/LAN/Serial 或選配功能正常','斷電重開後設定保存'],flow:[['確認配件/板件型號','依 PM45 accessory guide 核對。',['相容','不確定'],'不確定先停。'],['保存舊設定','Network/Port/選配/韌體。',['完成','無法取得'],'能留多少留多少。'],['安全拆裝','斷電、ESD、接頭/固定檢查。',['完成','發現異常'],'先修裝配。'],['初始化/設定','依官方指南完成必要設定。',['完成','仍不辨識'],'仍不辨識再查板件/主板。'],['實際負載驗證','用該介面連印/傳輸並重開機。',['通過','失敗'],'失敗保留症狀。']],sources:['honeywell_pm45_accessories','honeywell_pm45'],evidence:'source-backed'});
})();
